parameters.jsCode:
const MAX_REVIEW_ROUNDS=3;
const submitted=$input.item.json;
const original=$('Execute Workflow: Scouting Brief erstellen').first().json;
const reviewDecision=(submitted['Entscheidung']||'').toString().trim();
const reviewFeedback=(submitted['Feedback (Pflicht bei Request Changes)']||'').toString().trim();
const errors=[];
if(!['Approve','Request Changes','Reject'].includes(reviewDecision)) errors.push('Unbekannte Review-Entscheidung: '+reviewDecision);
if(reviewDecision==='Request Changes'&&!reviewFeedback) errors.push('Fuer \"Request Changes\" ist ein Feedback-Text erforderlich.');
const reviewRound=(original.scoutingBrief&&original.scoutingBrief.reviewRound)||1;
const maxRoundsReached=reviewDecision==='Request Changes'&&reviewRound>=MAX_REVIEW_ROUNDS;
const reviewOutcome=maxRoundsReached?'Reject':reviewDecision;
const valid=errors.length===0;
return [{json:{...original,reviewDecision,reviewFeedback,reviewOutcome,maxRoundsReached,valid,errorMessage:valid?undefined:'Die Review-Entscheidung ist ungueltig.\n\n'+errors.join('\n')}}];

const item=$input.item.json;
const reason=item.maxRoundsReached?`Die maximale Anzahl von ${item.scoutingBrief.maxReviewRounds} Ueberarbeitungsrunden fuer das Scouting Brief ist erreicht worden.`:'Der Sporting Director hat das Scouting Brief abgelehnt (Reject).';
const feedback=item.reviewFeedback?`

Feedback: ${item.reviewFeedback}`:'';
return [{json:{...item,errorMessage:`Die Kandidatensuche wurde nach der Human-Review kontrolliert beendet.

${reason}${feedback}`}}];

const item=$input.item.json||{};
const rawError=item.error;
const errorMessage=typeof rawError==='string'?rawError:(rawError&&rawError.message)?rawError.message:(item.errorMessage||'Es ist ein unbekannter Capability-Fehler aufgetreten.');
return [{json:{...item,errorMessage}}];
